mapper.select:
select mn.*, ifnull(detail.detailCount, 0) as detailCount from Sec_Expert_Audit_Group mn left join ( select seagd.Sea_id, count(1) as detailCount from Sec_Expert_Audit_Group_Detail seagd group by seagd.Sea_id ) detail on detail.Sea_id = mn.id
and mn.year=#{params.year}
and mn.state = #{params.state}
and mn.sea_name like concat('%', #{params.seaName}, '%')
and mn.create_uname like concat('%', #{params.createUname}, '%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
